import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, texture, normalMap, displacementMap, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ─────────────────────────────────────────────────────────────────
  // 1. ROOT GROUP
  // ─────────────────────────────────────────────────────────────────
  const group = new THREE.Group();
  group.userData.cleanup = () => {};
  group.userData.handlers = {};

  // ─────────────────────────────────────────────────────────────────
  // 2. GEOMETRY & MATERIAL SETUP
  // ─────────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(1.2, 0.75, 64, 64);

  // Parallax plane requires displacement + normal map
  const diffuseTex = await ctx.textureLoader.loadTexture(config.imageUrl);
  const depthTex = await ctx.textureLoader.loadTexture(config.depthMapUrl);

  // TSL displacement: map depth to local vertex offset
  const displacementIntensity = uniform(0.08);
  const displacementNode = mix(
    vec3(0),
    vec3(0, 0, 1),
    smoothstep(0.2, 0.8, texture(depthTex, uv()))
  ).mul(displacementIntensity);

  const material = new MeshStandardNodeMaterial({
    colorSpace: 'srgb',
    side: THREE.DoubleSide,
  });
  material.colorNode = texture(diffuseTex, uv());
  material.metalnessNode = uniform(0.45);
  material.roughnessNode = uniform(0.55);
  material.normalNode = normalMap(texture(depthTex, uv()));
  material.positionNode = positionLocal.add(displacementNode);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  group.add(mesh);

  // ─────────────────────────────────────────────────────────────────
  // 3. LIGHTING: RIM + ACCENT
  // ─────────────────────────────────────────────────────────────────
  const rimLight = new THREE.PointLight(0xff2a38, 0.75, 3.5);
  rimLight.position.set(1.2, 0.8, 1.5);
  rimLight.castShadow = false;
  group.add(rimLight);

  const fillLight = new THREE.PointLight(0xffffff, 0.4, 2.5);
  fillLight.position.set(-0.8, -0.5, 1.2);
  fillLight.castShadow = false;
  group.add(fillLight);

  // ─────────────────────────────────────────────────────────────────
  // 4. CINEMATIC PRIMITIVES
  // ─────────────────────────────────────────────────────────────────
  const primitiveCleanups = [];

  // Apply parallax-scroll on scroll trigger
  if (config.cinematicPrimitives?.some(p => p.name === 'parallax-scroll')) {
    const scrollResult = ctx.primitives['parallax-scroll'](mesh, {
      intensity: 0.4,
      axis: 'y',
    });
    if (scrollResult?.cleanup) primitiveCleanups.push(scrollResult.cleanup);
  }

  // Apply depth-rotate on hover trigger
  if (config.cinematicPrimitives?.some(p => p.name === 'depth-rotate')) {
    const rotateResult = ctx.primitives['depth-rotate'](mesh, {
      maxDeg: 8,
    });
    if (rotateResult?.cleanup) primitiveCleanups.push(rotateResult.cleanup);
  }

  // ─────────────────────────────────────────────────────────────────
  // 5. INTERACTIONS
  // ─────────────────────────────────────────────────────────────────
  let hoverTimeline = null;

  group.userData.handlers.pointerenter = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(mesh.position, {
      y: 0.15,
      duration: 0.5,
      ease: 'power3.out',
    });
  };

  group.userData.handlers.pointerleave = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.to(mesh.position, {
      y: 0,
      duration: 0.6,
      ease: 'power4.out',
    });
  };

  group.userData.handlers.click = () => {
    ctx.emit('hub-pricing.select', { source: 'pricing-row' });
  };

  // ─────────────────────────────────────────────────────────────────
  // 6. ENTRANCE ANIMATION
  // ─────────────────────────────────────────────────────────────────
  mesh.position.y = 0.3;
  mesh.material.opacity = 0;

  const entranceTimeline = gsap.timeline();
  entranceTimeline.to(mesh.position, {
    y: 0,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  entranceTimeline.to(mesh.material, {
    opacity: 1,
    duration: 0.5,
    ease: 'power2.out',
  }, 0.1);

  // ─────────────────────────────────────────────────────────────────
  // 7. CLEANUP
  // ─────────────────────────────────────────────────────────────────
  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    entranceTimeline.kill();
    primitiveCleanups.forEach(fn => fn?.());
    geometry.dispose();
    material.dispose();
    diffuseTex.dispose();
    depthTex.dispose();
  };

  return group;
}
